    if(type==='project_delivery')inputs+=field('deliveryNote','实际交付内容',{type:'textarea',required:true,wide:true})+field('acceptanceCriteria','验收标准与结果',{type:'textarea',required:true,wide:true});
    if(type==='weekly_report')inputs+=field('periodStart','开始日期',{type:'date',required:true})+field('periodEnd','结束日期',{type:'date',required:true})+field('summary','补充事项',{type:'textarea',wide:true,placeholder:'进展、阻塞事项或需要协调的问题'});
