  function renderUserForm(){const u=users.find(item=>item.id===view.id);if(!u)return renderEmpty('员工已变更，请刷新名册。');return `<form class="erp-form" data-erp-form="user" data-id="${e(u.id)}"><div class="erp-form-grid">${field('name','姓名',{required:true,value:u.name})}${field('department','部门',{value:u.department})}${field('title','岗位',{value:u.title})}${roleChecks(list(u.roles))}${u.status==='invited'?'<p class="erp-muted">员工尚未入驻，完成邀请后可登录。</p>':`<label class="erp-check-row erp-wide"><input type="checkbox" name="active" ${u.active!==false?'checked':''}>账号可以登录</label>`}</div>${formFooter('保存权限')}</form>`;}
  function renderDocumentResult(d){const result=renderBusinessResult(d,{calculation:activeRun?.calculation,quoteEvidence:activeRun?.quoteEvidence});if(result)return `<section class="erp-business-result" data-erp-update="result">${sectionHead(d.type==='weekly_report'?'周报内容':d.type==='project_delivery'?'验收内容':'办理内容')}${result}</section>`;if(d.agentStatus==='running'||activeRun?.status==='running')return `<div class="erp-processing" data-erp-update="result" role="status"><span class="erp-processing-mark" aria-hidden="true"></span><strong>处理中</strong></div>`;return ''; }
  function renderWeeklyFacts(d){if(d.type!=='weekly_report')return '';const record=snapshot.performance.find(p=>p.documentId===d.id),facts=record?.facts||d.input?.facts;if(!facts)return '';const taskFacts=list(facts.taskFacts),employeeRows=list(facts.employees),counts=weeklyDocumentCounts(facts);return `${sectionHead(record?'已确认工作记录':'本期工作记录')}<p class="erp-period-totals"><strong>${counts.documentCount}份业务单据</strong><span>${counts.typeCount}种业务类型</span></p><div class="erp-overview">${[['已验收任务',facts.completedTasks??0],['本期提交',facts.submittedTasks??0],['期末未结',facts.pendingTasks??0],['期末逾期',facts.overdueTasks??0]].map(([label,value])=>`<div class="erp-stat"><span>${label}</span><strong>${e(value)}</strong></div>`).join('')}</div>${table(['员工','本期分配','本期提交','已验收','待验收','期末未结','期末逾期','交付验收'],employeeRows.map(item=>[e(userName(item.employeeId)),e(item.assignedTasks??0),e(item.submittedTasks??0),e(item.completedTasks??0),e(taskFacts.filter(t=>t.assigneeIdAtPeriodEnd===item.employeeId&&t.stateAtPeriodEnd==='submitted').length),e(item.pendingTasks??0),e(item.overdueTasks??0),e(item.acceptedDeliveries??0)]),'本期无员工工作记录。')}${list(facts.tasks).length?sectionHead('本期已验收任务')+table(['任务','负责人','验收人','验收日期'],list(facts.tasks).map(t=>[e(t.title),e(userName(t.employeeId)),e(userName(t.acceptedBy)),e(dateText(t.completedAt))])):''}${taskFacts.length?`<details class="erp-history"><summary>期末任务明细</summary>${table(['任务','负责人','期末状态','截止日期'],taskFacts.map(t=>[e(t.title),e(userName(t.assigneeIdAtPeriodEnd)),renderStatus(t.stateAtPeriodEnd==='completed'?'accepted':t.stateAtPeriodEnd),e(t.dueDate||'—')]))}</details>`:''}`;}
  function renderDocumentContent(d){
    if(d.type!=='weekly_report')return renderDocumentResult(d);
    const result=renderBusinessResult(d,{calculation:activeRun?.calculation,quoteEvidence:activeRun?.quoteEvidence});
    return `<div data-erp-update="weekly-facts">${renderWeeklyFacts(d)}</div>`+(result?`<details class="erp-history" data-erp-disclosure="weekly-review"><summary>核对说明</summary><section class="erp-business-result">${result}</section></details>`:renderDocumentResult(d));
  }
  function renderDetail(){const d=activeDocument;if(!d)return renderEmpty('正在读取单据…');const approvals=list(d.approvals),input=d.input||{},moves=snapshot.movements.filter(m=>m.documentId===d.id),run=activeRun||{};const files=list(d.artifacts).filter(f=>safeFileUrl(f.url||f.downloadUrl));if(safeFileUrl(d.reportUrl)&&!files.some(f=>f.url===d.reportUrl))files.unshift({name:'办理报告',url:d.reportUrl});return `<div class="erp-document-top" data-erp-update="status"><div>${renderStatus(d.agentStatus==='running'?'agent_running':d.agentStatus==='failed'?'agent_failed':d.status)}${d.status==='awaiting_approval'&&d.approvalChain?.[d.approvalIndex]?`<span class="erp-muted">待${e(roleName(d.approvalChain[d.approvalIndex]))}审批</span>`:''}</div><div class="erp-actions">${renderActions(d)}</div></div>${d.error||run.error?`<div class="erp-form-errors">${e(businessError(d.error||run.error))}</div>`:''}${renderDocumentContent(d)}<dl class="erp-detail-summary">${[['编号',d.number||d.id],['项目',project(d.projectId).name||'—'],['申请人',userName(d.requesterId||d.createdBy)],['创建日期',dateText(d.createdAt)]].map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}</dl>${sectionHead('申请资料')}<dl class="erp-kv">${Object.entries(input).filter(([key])=>key!=='facts').map(([key,value])=>`<dt>${e(INPUT_LABELS[key]||key)}</dt><dd>${e(key==='employeeId'?userName(value):key==='operation'?OP_LABELS[value]||value:textValue(value))}</dd>`).join('')}</dl>${list(d.lines).length?`${sectionHead('产品明细')}${table(['产品',d.type==='stocktake'?'实盘 / 账面':'申请数量','单价','金额','已办理'],d.lines.map(line=>[e(line.productName||line.name||product(line.productId).name||line.productId),e(d.type==='stocktake'?`${line.countedQuantity??line.quantity} / ${line.systemQuantity??'—'}`:line.quantity),line.unitPriceCents!=null?money(line.unitPriceCents):'—',line.unitPriceCents!=null?money(Number(line.quantity||0)*Number(line.unitPriceCents)):'—',e(line.completedQuantity??line.receivedQuantity??line.shippedQuantity??line.postedQuantity??0)]))}`:''}${d.confirmation?.reference?sectionHead('办理确认')+`<dl class="erp-kv"><dt>办理凭证</dt><dd>${e(d.confirmation.reference)}</dd><dt>办理人</dt><dd>${e(d.confirmation.actorName||userName(d.confirmation.actorId))}</dd><dt>办理日期</dt><dd>${e(dateText(d.confirmation.createdAt))}</dd><dt>办理意见</dt><dd>${e(d.confirmation.note||'—')}</dd></dl>`:''}${moves.length?sectionHead('出入库记录')+renderMovements(moves):''}${approvals.length?sectionHead('审批记录')+table(['审批人','结果','意见','日期'],approvals.map(a=>[e(a.actorName||userName(a.actorId)),e(statusLabel(a.decision||a.status)),e(a.note||'—'),e(dateText(a.createdAt))])):''}${list(d.approvalHistory).length?`<details class="erp-history"><summary>历史审批</summary>${table(['审批人','结果','意见','日期'],d.approvalHistory.map(a=>[e(a.actorName||userName(a.actorId)),e(statusLabel(a.decision)),e(a.note||'—'),e(dateText(a.createdAt))]))}</details>`:''}${files.length?`<details class="erp-history"><summary>导出文件</summary><ul class="erp-file-list">${renderFiles(files)}</ul></details>`:''}`;}
  function renderActionForm(){const d=activeDocument,a=view.operation;if(!d)return renderEmpty('请重新打开业务单。');const fill=['receive','ship'].includes(a),returned=['return','reject'].includes(a),needsReference=['receive','ship','post','complete'].includes(a),lines=list(d.lines),key=a==='receive'?'receivedQuantity':'shippedQuantity';return `<form class="erp-form" data-erp-form="action" data-id="${e(d.id)}" data-operation="${e(a)}"><div class="erp-approval-box ${returned?'erp-decision-return':'erp-decision-confirm'}"><div class="erp-approval-heading"><span class="erp-approval-symbol" aria-hidden="true"><svg viewBox="0 0 24 24"><use href="#${returned?'i-reset':'i-check'}"></use></svg></span><div><h2>${e(ACTION_LABELS[a]||'确认办理')}</h2><p>${e(d.title)} · ${e(workflowName(d.type))}</p></div></div><div class="erp-approval-content">${['approve','return','reject'].includes(a)?renderDocumentContent(d):''}<div class="erp-decision-fields">${needsReference?field('reference',a==='receive'?'收货凭证号':a==='ship'?'发货凭证号':'办理凭证号',{required:true,placeholder:'填写实际单号或可追溯凭证'}):''}${fill?`<div class="erp-line-list">${lines.map((line,index)=>{const remaining=Math.max(0,Number(line.quantity)-Number(line.completedQuantity??line[key]??0));return `<div data-erp-line="${index}">${field(`line_quantity_${index}`,`${line.productName||line.name||product(line.productId).name||line.productId} · 待${a==='receive'?'收':'发'} ${remaining}`,{type:'number',value:'',min:0,max:remaining,step:'1'}).replace('<input ','<input data-line-field="quantity" ')}<input type="hidden" data-line-field="lineId" value="${e(line.id||line.lineId)}"></div>`;}).join('')}</div>`:''}${field('note',returned?'退回原因':'办理意见',{type:'textarea',required:returned||d.type==='stocktake'&&['post','complete'].includes(a),placeholder:returned?'说明需要修改的内容':'填写实际核对情况'})}</div><div class="erp-approval-actions">${button('返回业务单','open-document',`data-id="${e(d.id)}"`)}<button type="submit" class="erp-button ${returned?'erp-danger':'erp-primary'}">${e(ACTION_LABELS[a]||'确认')}</button></div></div></div></form>`;}
  function renderTaskReassign(){const task=snapshot.tasks.find(item=>item.id===view.id),p=project(task?.projectId),ids=new Set([...(p.members||[]),p.ownerId]);return `<form class="erp-form" data-erp-form="task-reassign" data-id="${e(view.id)}"><div class="erp-note">${e(task?.title||'任务')} · 当前负责人：${e(userName(task?.assigneeId))}</div>${field('assigneeId','接替员工',{required:true,options:options(users.filter(item=>item.active!==false&&ids.has(item.id)))})}${field('note','转派原因',{type:'textarea',required:true})}${formFooter('确认转派')}</form>`;}
  function renderTaskComplete(){const task=snapshot.tasks.find(item=>item.id===view.id),review=view.mode==='task-review',reject=['return','reject'].includes(view.operation);if(review)return `<form class="erp-form" data-erp-form="task-review" data-id="${e(view.id)}" data-operation="${e(view.operation)}"><div class="erp-approval-box ${reject?'erp-decision-return':'erp-decision-confirm'}"><div class="erp-approval-heading"><span class="erp-approval-symbol" aria-hidden="true"><svg viewBox="0 0 24 24"><use href="#${reject?'i-reset':'i-check'}"></use></svg></span><div><h2>${e(task?.title||'工作任务')}</h2></div></div><div class="erp-approval-content"><div class="erp-reading">${e(task?.result||'暂无交付说明')}</div>${list(task?.evidence).map(item=>`<div class="erp-note"><strong>${e(item.name||'凭证')}</strong><br>${e(item.reference||textValue(item))}</div>`).join('')}<div class="erp-decision-fields">${field('note',reject?'退回原因':'验收意见',{type:'textarea',required:reject})}</div>${formFooter(reject?'退回补正':'确认验收','返回','erp-approval-actions')}</div></div></form>`;return `<form class="erp-form" data-erp-form="task-complete" data-id="${e(view.id)}">${field('result','交付说明',{type:'textarea',required:true,placeholder:task?.title||'填写实际完成的工作'})}${field('evidence','交付记录或凭证',{type:'textarea',required:true,placeholder:'每行填写一项文档地址、交付编号或可核对的记录'})}${formFooter('提交交付')}</form>`;}
  async function openDocument(id){if(!opened)await open();activeDocument=snapshot.documents.find(item=>item.id===id)||null;activeRun=null;navigate({section:'detail',id});const epoch=loadEpoch;try{const data=await call('/api/erp/workitems/'+encodeURIComponent(id));if(!opened||view.section!=='detail'||view.id!==id||epoch!==loadEpoch)return;activeDocument={...documentFrom(data),...(data.reportUrl?{reportUrl:data.reportUrl}:{})};activeRun=data.run||activeDocument.run||activeDocument.agentRun||null;render();notifyNavigation();}catch(err){showError(err);}}
  function syncViewActions(){for(const control of root.querySelectorAll('[data-erp-action="view"]')){control.setAttribute('aria-pressed',String(scene?.mode===control.dataset.mode));control.setAttribute('aria-busy',String(sceneChanging));control.disabled=sceneChanging&&control.dataset.mode==='3d';}}
  async function switchView(mode){if(!scene||!['2d','3d'].includes(mode))return;const epoch=++sceneChangeEpoch;sceneChanging=true;syncViewActions();try{await scene.setMode(mode);}catch(err){showError(err);}finally{if(epoch===sceneChangeEpoch){sceneChanging=false;syncViewActions();}}}
  async function handleAction(event){if(!opened||destroyed)return;const el=event.target.closest?.('[data-erp-action]');if(!el||!root.contains(el))return;const action=el.dataset.erpAction;if(action==='close'){close();return;}if(action==='view'){await switchView(el.dataset.mode);return;}if(busy)return;try{
    if(action==='section'){navigate({section:el.dataset.section});return;}if(action==='inventory-tab'){navigate({section:'inventory',tab:el.dataset.tab});return;}if(action==='report-tab'){navigate({section:'reports',tab:el.dataset.tab});return;}if(action==='filter-documents'){statusFilter=el.dataset.filter;render();return;}if(action==='person'){navigate({section:'people',focusEmployeeId:el.dataset.id});return;}if(action==='project-focus'){navigate({section:'projects',focusProjectId:el.dataset.id});return;}
    if(action==='refresh'){await refresh();return;}
    if(action==='back'){back();return;}
    if(action==='all-documents'){navigate({section:'flows'});return;}
    if(action==='new-document'){navigate({section:'flows',mode:'create',type:el.dataset.type,projectId:el.dataset.projectId});return;}
    if(action==='new-master'){navigate({section:el.dataset.kind==='project'?'projects':'products',mode:'create',kind:el.dataset.kind});return;}
    if(action==='edit-project'){const record=project(el.dataset.id);navigate({section:'projects',mode:'edit-project',kind:'project',id:record.id});drafts.set(draftKey,{values:{name:record.name,customer:record.customer,ownerId:record.ownerId,members:record.members},rows:[]});render();return;}if(action==='task-reassign'){navigate({section:'projects',mode:'task-reassign',id:el.dataset.id});return;}if(action==='new-task'){navigate({section:'projects',mode:'create',kind:'task',projectId:el.dataset.id});return;}
    if(action==='password'){navigate({section:'people',mode:'password'});return;}if(action==='reset-user'){navigate({section:'people',mode:'reset-user',id:el.dataset.id,operation:el.dataset.operation==='reinvite'?'invite':el.dataset.operation||'reset'});return;}if(action==='invite'){navigate({section:'people',mode:'invite'});return;}
    if(action==='edit-user'){navigate({section:'people',mode:'edit-user',id:el.dataset.id});return;}
    if(action==='open-document'){await openDocument(el.dataset.id);return;}
    if(action==='document-action'){const id=assertAllowedAction(activeDocument,el.dataset.operation);if(id==='revise'){const d=activeDocument;view={section:'flows',mode:'revise',type:d.type,id:d.id,projectId:d.projectId};draftKey=keyFor(view);drafts.set(draftKey,{values:{title:d.title,projectId:d.projectId,...d.input},rows:list(d.lines).map(line=>({productId:line.productId,quantity:String(line.quantity),countedQuantity:String(line.countedQuantity??line.quantity),unitPrice:String((line.unitPriceCents||0)/100)}))});error='';render();return;}navigate({section:'detail',mode:'action',operation:id,id:activeDocument.id});return;}
    if(action==='task-review'){navigate({section:'projects',mode:'task-review',operation:el.dataset.operation,id:el.dataset.id});return;}if(action==='task-complete'){navigate({section:'projects',mode:'task-complete',id:el.dataset.id});return;}
    if(action==='add-line'||action==='remove-line'){capture();const saved=drafts.get(draftKey)||{values:{},rows:[]};if(action==='add-line')saved.rows.push({productId:'',quantity:'1',unitPrice:'',countedQuantity:'0'});else saved.rows.splice(Number(el.dataset.index),1);drafts.set(draftKey,saved);render();return;}
    if(action==='export'){downloadExport(el.dataset.kind);return;}if(action==='copy-invite'){if(!inviteSecret)return;try{await navigator.clipboard.writeText(inviteSecret.url);flash='邀请链接已复制。';render();}catch{showError(new Error('浏览器未允许复制，请选中链接手动复制。'));}return;}
    if(action==='dismiss-invite'){inviteSecret=null;render();return;}
  }catch(err){showError(err);}}
  function valuesFrom(form){const values={};for(const input of form.elements){if(!input.name||input.type==='button'||input.type==='submit')continue;if(['roles','members'].includes(input.name)){values[input.name]||=[];if(input.checked)values[input.name].push(input.value);}else values[input.name]=input.type==='checkbox'?input.checked:input.value.trim();}return values;}
  async function handleSubmit(event){const form=event.target.closest?.('[data-erp-form]');if(!opened||destroyed||!form||!root.contains(form))return;event.preventDefault();if(busy)return;capture();if(!form.reportValidity())return;const submittedKey=draftKey,submissionEpoch=loadEpoch,stay=()=>opened&&submissionEpoch===loadEpoch&&draftKey===submittedKey;setBusy(true,form);showError('');try{const values=valuesFrom(form);let result;const kind=form.dataset.erpForm;
    if(kind==='password'){if(values.newPassword.length<12)throw new Error('新密码至少需要 12 个字符。');if(values.newPassword!==values.confirmPassword)throw new Error('两次新密码不一致。');await call('/api/erp/identity/password','POST',{currentPassword:values.currentPassword,newPassword:values.newPassword});form.reset();close({immediate:true});document.dispatchEvent(new CustomEvent('office:session-ended',{bubbles:true}));return;}if(kind==='reset-user'){result=await call('/api/erp/users/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(form.dataset.operation||'reset'),'POST',{});const token=result.token||result.invitation?.token;if(!token)throw new Error('密码重设已提交，请核对服务返回的邀请记录。');inviteSecret={url:location.origin+'/join#token='+encodeURIComponent(token),expiresAt:result.expiresAt||result.invitation?.expiresAt};navigate({section:'people'});render();return;}if(kind==='document'){const revised=view.mode==='revise';const payload=buildDocumentPayload(form.dataset.type,values,currentRows);if(view.mode==='revise'){delete payload.type;delete payload.projectId;payload.expectedVersion=activeDocument.version;result=await call('/api/erp/workitems/'+encodeURIComponent(form.dataset.id)+'/revise','POST',payload);}else result=await call('/api/erp/workitems','POST',payload);drafts.delete(submittedKey);const d=documentFrom(result);let processingError;if(revised){try{await call('/api/erp/workitems/'+encodeURIComponent(d.id)+'/run_agents','POST',{expectedVersion:d.version});}catch(err){processingError=err;}}await refresh({silent:true});if(!stay())return;await openDocument(d.id);if(!opened||submissionEpoch!==loadEpoch||view.section!=='detail'||view.id!==d.id)return;flash=revised?'修改已保存。':'申请已提交。';render();if(processingError&&!['running','queued','completed'].includes(activeRun?.status))showError(processingError);return;}
    if(kind==='master'){const record=form.dataset.kind==='product'?{name:values.name,sku:values.sku,unit:values.unit,priceCents:parsePrice(values.price)}:{name:values.name,customer:values.customer,ownerId:values.ownerId,members:[...new Set([...(values.members||[]),values.ownerId])]};if(view.mode==='edit-project')result=await call('/api/erp/projects/'+encodeURIComponent(form.dataset.id),'PUT',record);else result=await call('/api/erp/masterdata','POST',{kind:form.dataset.kind==='product'?'products':'projects',record});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:form.dataset.kind==='product'?'products':'projects'});flash='已保存。';render();return;}
    if(kind==='invite'){result=await call('/api/erp/invitations','POST',{name:values.name,username:values.username,department:values.department,title:values.title,roles:values.roles||[]});const invitation=result.invitation||result,token=result.token||invitation.token;if(!token)throw new Error('邀请已创建，但服务未返回邀请链接。请在员工记录中核对。');inviteSecret={url:location.origin+'/join#token='+encodeURIComponent(token),expiresAt:invitation.expiresAt||result.expiresAt};drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'people'});render();return;}
    if(kind==='user'){await call('/api/erp/users/'+encodeURIComponent(form.dataset.id),'PUT',{name:values.name,department:values.department,title:values.title,roles:values.roles||[],active:values.active});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'people'});flash='员工资料与权限已保存。';render();return;}
    if(kind==='task-reassign'){const task=snapshot.tasks.find(item=>item.id===form.dataset.id);if(!list(task?.allowedActions).includes('reassign'))throw new Error('当前任务不能转派，请刷新任务。');if(!values.note)throw new Error('请填写转派原因。');await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/reassign','POST',{assigneeId:values.assigneeId,note:values.note});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'projects'});flash='任务已转派。';render();return;}if(kind==='task'){await call('/api/erp/tasks','POST',{projectId:values.projectId,title:values.title,assigneeId:values.assigneeId,dueDate:values.dueDate||undefined});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'projects'});flash='任务已登记。';render();return;}
    if(kind==='task-review'){await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(form.dataset.operation),'POST',{note:values.note});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'projects'});flash=form.dataset.operation==='accept'?'交付已验收。':'任务已退回补正。';render();return;}if(kind==='task-complete'){await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/complete','POST',{result:values.result,evidence:values.evidence.split(/\n+/).map(item=>item.trim()).filter(Boolean).map(reference=>({name:'交付凭证',reference}))});drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;navigate({section:'projects'});flash='交付已提交，等待负责人验收。';render();return;}
    if(kind==='action'){const action=assertAllowedAction(activeDocument,form.dataset.operation),payload={note:values.note||'',expectedVersion:activeDocument.version};if((['return','reject'].includes(action)||activeDocument.type==='stocktake'&&['post','complete'].includes(action))&&!payload.note)throw new Error(activeDocument.type==='stocktake'&&['post','complete'].includes(action)?'请填写盘点办理核对意见。':'请填写退回原因。');if(['receive','ship','post','complete'].includes(action)){if(!values.reference)throw new Error('请填写办理凭证号。');payload.reference=values.reference;if(['receive','ship'].includes(action))payload.lines=fulfillmentLines(activeDocument,currentRows,action);}await call('/api/erp/workitems/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(action),'POST',payload);drafts.delete(submittedKey);await refresh({silent:true});if(!stay())return;await openDocument(form.dataset.id);if(!opened||submissionEpoch!==loadEpoch||view.section!=='detail'||view.id!==form.dataset.id)return;flash=action==='approve'?'本次审批已通过。':['return','reject'].includes(action)?'已退回补正。':action==='receive'?'本次收货已登记。':action==='ship'?'本次发货已登记。':['run_agents','run_agent','retry_agent'].includes(action)?'已提交处理。':'办理结果已登记。';render();return;}
  }catch(err){showError(err);}finally{setBusy(false);}}
  function downloadExport(kind){let headers,rows,name;if(kind==='inventory'){headers=['产品编码','产品','单位','当前数量'];rows=snapshot.inventory.map(item=>[item.sku||product(item.productId).sku,item.name||product(item.productId).name,item.unit||product(item.productId).unit,item.quantity]);name='库存台账';}else{headers=['员工','项目','开始日期','结束日期','已验收任务数','期间提交','待验收','待办','逾期','交付验收','确认人','业务单号'];rows=snapshot.performance.flatMap(record=>list(record.facts?.employees).map(item=>[userName(item.employeeId),project(record.projectId).name,record.periodStart,record.periodEnd,item.completedTasks,item.submittedTasks??0,list(record.facts?.taskFacts).filter(task=>task.stateAtPeriodEnd==='submitted'&&task.assigneeIdAtPeriodEnd===item.employeeId).length,item.pendingTasks??0,item.overdueTasks??0,item.acceptedDeliveries??0,userName(record.confirmedBy),record.documentId]));name='员工工作记录';}if(!rows.length){showError(new Error('暂无可导出的已确认记录。'));return;}const url=URL.createObjectURL(new Blob([csvDocument(headers,rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'-'+new Date().toISOString().slice(0,10)+'.csv';document.body.append(a);a.click();a.remove();const revoke=()=>URL.revokeObjectURL(url),timer=setTimeout(()=>{downloadTimers.delete(timer);revoke();},1000);downloadTimers.set(timer,revoke);}
  function onKey(event){if(!opened)return;if(event.key==='Escape'&&!busy){event.preventDefault();close();}}
  function handleChange(event){capture();const name=event.target?.name;if(view.type==='resource'&&['employeeId','operation','originalDocumentId'].includes(name)){const saved=drafts.get(draftKey);if(name==='originalDocumentId'&&saved?.values?.operation==='return'){const source=returnSources(saved.values.employeeId).find(d=>d.id===saved.values.originalDocumentId);if(source)saved.values.projectId=source.projectId||'';}render();}else if(name==='projectId'&&view.kind==='task')render();}function onVisibility(){if(opened&&document.visibilityState==='visible')void refresh({silent:true});}
  root.addEventListener('click',handleAction);root.addEventListener('submit',handleSubmit);root.addEventListener('input',capture);root.addEventListener('change',handleChange);document.addEventListener('keydown',onKey);document.addEventListener('visibilitychange',onVisibility);
  async function open(section='desk',context={}){if(destroyed)return;const wasOpen=opened;if(wasOpen)capture();if(!wasOpen)previousFocus=document.activeElement;cancelAnimations();panelEpoch++;opened=true;root.hidden=false;root.inert=false;root.setAttribute('aria-hidden','false');loadEpoch++;draftKey='';view={section:SECTIONS.some(([id])=>id===section)?section:'desk',...context};draftKey=keyFor(view);error='';if(!wasOpen)flash='';render();notifyNavigation();if(!wasOpen){root.querySelector('[data-erp-action="close"]')?.focus();animate(root,[{opacity:0,transform:'translateX(26px) scale(.99)'},{opacity:1,transform:'translateX(0) scale(1)'}],280);}if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(()=>{if(opened&&!busy&&document.visibilityState!=='hidden')void refresh({silent:true});},4000);await refresh();}
  function close({immediate=false}={}){if(!opened){if(immediate){cancelAnimations();releaseDownloads();finishClose();}return;}capture();opened=false;loadEpoch++;const epoch=++panelEpoch;cancelAnimations();releaseDownloads();root.inert=true;root.setAttribute('aria-hidden','true');renderedViewKey='';renderedMarkup='';inviteSecret=null;flash='';if(pollTimer)clearInterval(pollTimer);pollTimer=null;previousFocus?.focus?.({preventScroll:true});notifyNavigation();onClose();if(immediate)finishClose();else animate(root,[{opacity:1,transform:'translateX(0) scale(1)'},{opacity:0,transform:'translateX(20px) scale(.995)'}],170,()=>{if(!opened&&epoch===panelEpoch)finishClose();});}
  function destroy(){close({immediate:true});destroyed=true;cancelAnimations();releaseDownloads();motionPreference?.removeEventListener?.('change',onMotionPreference);root.removeEventListener('click',handleAction);root.removeEventListener('submit',handleSubmit);root.removeEventListener('input',capture);root.removeEventListener('change',handleChange);document.removeEventListener('keydown',onKey);document.removeEventListener('visibilitychange',onVisibility);root.remove();drafts.clear();mutationKeys.clear();snapshot=normalizeSnapshot();users=[];invitations=[];activeDocument=null;activeRun=null;catalog={};session={};currentRows=[];draftKey='';error='';flash='';previousFocus=null;}
  return {open,close,destroy,refresh,openDocument,openPerson(id){return open('people',{focusEmployeeId:id});},updateSession(value){session=value||{};if(opened)render();},get isOpen(){return opened;},get state(){return {section:view.section,mode:view.mode,snapshot,currentUser:actor(),busy};}};
